        override val covIntroClawbackAnalogy = "تخيلها كخزينة بنك بإنذار صامت وفترة انتظار قبل خروج الأموال."
        override val covIntroClawbackWhat = "أي سحب يجب أن ينتظر مهلة الأمان أولاً لمنحك وقتاً لاكتشاف أي محاولة غير مصرح بها."
        override val covIntroClawbackHow = "اضغط بدء السحب وانتظر انتهاء العد التنازلي ثم اضغط إكمال السحب — أو فعّل الاسترداد الطارئ في أي وقت من محفظة المالك."
        override val covIntroClawbackBack = "أكمل السحب بعد المهلة، أو فعّل الاسترداد الطارئ في أي لحظة لتحويل الرصيد لعنوانك الآمن."
        override val covIntroDeadManAnalogy = "تخيلها كوصية رقمية دون وسطاء مع تسجيل حضور دوري."
        override val covIntroDeadManWhat = "تبقي KAS تحت سيطرتك طالما تسجّل حضورك دورياً، وتفتحه لوريثك فقط عند توقفك."
        override val covIntroDeadManHow = "اضغط تسجيل حضور بلمسة واحدة قبل انتهاء المهلة لإعادة ضبطها، وشارك ملف .kpass أو QR مع وريثك."
        override val covIntroDeadManBack = "ألغِ واسترد 100% في أي وقت، أو دع وريثك يستلم برصيد 0 KAS بعد انقضاء المهلة."
        override val covIntroWhitelistAnalogy = "تخيلها كممر أمان باتجاه واحد — لا تتحرك الأموال إلا لعناوينك الباردة المعتمدة."
        override val covIntroWhitelistWhat = "حتى لو سُرق هاتفك، يرفض معدّنو Kaspa أي معاملة لا تدفع لأحد عناوينك الباردة الـ 1–3."
        override val covIntroWhitelistHow = "أودع أو اشحن KAS ثم أرسل مبالغ جزئية أو كاملة حصرياً لعناوينك الباردة المعتمدة."
        override val covIntroWhitelistBack = "اضغط إرسال إلى عنوان معتمد في أي وقت لنقل الرصيد إلى محفظتك الباردة."
        override val covIntroHodlAnalogy = "تخيلها ككبسولة زمنية غير قابلة للكسر للحفظ طويل الأمد."
        override val covIntroHodlWhat = "تقفل KAS على الطبقة الأولى لـ Kaspa حتى التاريخ والوقت الدقيقين — لا يمكن لأحد فتحها مبكراً."
        override val covIntroHodlHow = "تابع العد التنازلي المباشر وأضف المزيد من KAS عبر الشحن داخل التطبيق دون تغيير موعد الفتح."
        override val covIntroHodlBack = "عند وصول العد التنازلي إلى الصفر، اضغط فتح وسحب الكل لإعادة 100% إلى محفظتك."
        override val covIntroPiggyAnalogy = "تخيلها كحصالة تُفتح فور بلوغ هدف KAS — مع تاريخ أمان احتياطي حتى لا تعلق أموالك."
        override val covIntroPiggyWhat = "تحمي مدخراتك حتى بلوغ الهدف، مع ضمان تاريخ فتح احتياطي آمن."
        override val covIntroPiggyHow = "نمِّ مدخراتك عبر الشحن (مع زر إكمال المتبقي بلمسة واحدة) — وتُدفع الرسوم من محفظتك لا من الإيداع."
        override val covIntroPiggyBack = "اضغط فتح (تم بلوغ الهدف) فور وصول الرصيد، أو فتح (تاريخ الأمان) عند حلول الموعد."
        override val covIntroRecurringAnalogy = "تخيلها كصندوق مصروف مسبق الدفع يحرر مبلغاً ثابتاً حسب الجدول — ويمكنك إلغاؤه في أي وقت."
        override val covIntroRecurringWhat = "يحرر مبلغ KAS ثابتاً في كل دورة مباشرة للمستلم مع إبقاء بقية الصندوق مقفلة على السلسلة."
        override val covIntroRecurringHow = "موّل خزينة KAS وشارك ملف أو رمز QR الخاص ببطاقة .kpass مع المستلم، ليقوم باستيرادها في المشتركة والضغط على مطالبة في الموعد المحدد (يكفي وجود 0.00 KAS في محفظته)."
        override val covIntroRecurringBack = "اضغط إلغاء واسترداد المتبقي في أي وقت كمالك لسحب جميع KAS المتبقية فوراً."
        override val covRealWorldScenarioLabel = "سيناريو واقعي"
        override val covSyncingStatus = "جارٍ المزامنة..."
        override val covIntroWhitelistScenario = "حتى لو تم اختراق هاتفك أو محفظتك الساخنة، لا يمكن للأموال داخل هذه الخزينة الانتقال إلا إلى عناوينك الـ 1–3 المعتمدة مسبقاً. وجّهها إلى محافظ باردة تتحكم بها، ولن يتمكن أي مهاجم من سرقة عملات KAS الخاصة بك."
        override val covIntroHodlScenario = "هل تريد الاحتفاظ بـ KAS على المدى الطويل دون بيع بدافع الذعر أثناء الهبوط؟ اقفلها حتى تاريخ مستقبلي، ولن يتمكن أحد — ولا حتى أنت — من تحريكها قبل حلول ذلك الموعد."
        override val covIntroDailyScenario = "حافظ على أمان رصيد KAS اليومي على هاتفك. حتى لو حصل شخص على وصول إلى محفظتك، فلن يتمكن من سحب أكثر من حدك اليومي في كل فترة، مما يمنحك مهلة لتأمين أموالك."
        override val covIntroClawbackScenario = "تخيلها كجهاز إنذار أمان لمدخراتك. إذا حاول مهاجم تفريغ خزينتك، يتوقف السحب مؤقتاً خلال مهلة الأمان لتتمكن من الضغط على الاسترداد الطارئ الفوري ونقل كل شيء مباشرة إلى عنوان الاسترداد الآمن."
        override val covIntroPiggyScenario = "هل تدّخر 10,000 KAS لشراء حاسوب محمول جديد أو السفر؟ واصل شحن الخزينة بمرور الوقت؛ تبقى مقفلة حتى تبلغ هدفك، مع تاريخ أمان احتياطي حتى لا تعلق عملاتك أبداً إذا تغيّرت خططك."
        override val covIntroDeadManScenario = "تأكد من أن عائلتك لن تفقد عملات KAS الخاصة بك إذا حدث لك مكروه. اضغط تسجيل حضور كل بضعة أشهر؛ وإذا توقفت عن تسجيل الحضور، يمكن لوريثك المطالبة بكامل الرصيد تلقائياً دون مشاركة أي عبارة استرداد."
        override val covIntroRecurringScenario = "أنشئ مصروفاً أسبوعياً لأحد أفراد عائلتك أو دفعة شهرية لصديق دون الاعتماد على وسيط. موّل الصندوق مرة واحدة، ولن يتمكن المستلم إلا من المطالبة بالمبلغ المحدد في كل دورة بينما يمكنك الإلغاء واسترداد المتبقي في أي وقت."
